fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher and choose 'Bulk Operations' so the Operations studio list is showing. Type a query into the 'Search bulk operations…' box at the top of the list. Verify the list RESPONDS — the visible rows narrow to operations whose name or entity matches, OR a clear empty result appears if nothing matches. Then clear the box and confirm the full list returns. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. This is data-agnostic: a narrowed list, an empty result, or the empty-state (if there are no operations at all) are all valid responses to the search.",
  "startUrl": "http://localhost:4200/app/bulk-operations",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Typing in the 'Search bulk operations…' box visibly filters the operations list (fewer/no matching rows) rather than being inert",
    "Clearing the search restores the previous list",
    "No error messages, blank screens, or crash pages"
  ]
}
